text:
```yaml
design:
  schema: fpga-design-agent/project/v1
  name: vmed
  board: nexys_a7_100t
  clocks:
    - {name: clk_sys, source: board, port: CLK100MHZ, mhz: 100}
    - {name: clk_video, source: mmcm, from: clk_sys, mhz: 74.25}
  resets:
    - {name: rst_sys, domain: clk_sys, polarity: active_low, style: async, from: CPU_RESETN}
    - {name: rst_video, domain: clk_video, polarity: active_high, style: sync, from: rst_sys, via: reset_sync}
  shell: {design_id: VMED, clock: clk_sys, reset: rst_sys}
  modules:
    - name: pixel_clock
      kind: rtl
      clocks: {clk: clk_sys}
      resets: {rst: rst_sys}
    - name: timing_gen
      kind: rtl
      clocks: {clk: clk_video}
      resets: {rst: rst_video}
      window_base: 0x04
      register_crossings: {FRAME_COUNT: xpm_cdc_gray}
    - name: pattern_gen
      kind: rtl
      clocks: {clk: clk_video}
      resets: {rst: rst_video}
      window_base: 0x00
      register_crossings: {PATTERN: xpm_cdc_single}
    - name: median_filter
      kind: rtl
      clocks: {clk: clk_video}
      resets: {rst: rst_video}
    - name: vga_output
      kind: rtl
      clocks: {clk: clk_video}
      resets: {rst: rst_video}
  connections:
    - {from: timing_gen.out, to: pattern_gen.in}
    - {from: pattern_gen.out, to: median_filter.in}
    - {from: median_filter.out, to: vga_output.in}
  board_ports:
    - {name: CLK100MHZ, dir: in, drive: input, to: clk_sys}
    - {name: CPU_RESETN, dir: in, drive: input, to: rst_sys}
    - {name: UART_TXD_IN, dir: in, drive: input, to: shell.uart_rx}
    - {name: UART_RXD_OUT, dir: out, drive: push-pull, from: shell.uart_tx}
    - {name: BTNC, dir: in, drive: input, to: vga_output.blank_button}
    - {name: "LED[0]", dir: out, drive: push-pull, from: clk_video.locked}
    - {name: "VGA_R[3:0]", dir: out, drive: push-pull, from: vga_output.red}
    - {name: "VGA_G[3:0]", dir: out, drive: push-pull, from: vga_output.green}
    - {name: "VGA_B[3:0]", dir: out, drive: push-pull, from: vga_output.blue}
    - {name: VGA_HS, dir: out, drive: push-pull, from: vga_output.hsync}
    - {name: VGA_VS, dir: out, drive: push-pull, from: vga_output.vsync}
  owned: []
  assumptions:
    - id: A-1
      text: "Use CPU_RESETN as the configuration/runtime reset input; BTNC remains only a video-blanking control."
      default: "rst_sys is active-low asynchronous; rst_video is active-high synchronous and synchronized into clk_video."
      reason: "The specification assigns BTNC to blanking and does not specify a reset source or reset implementation."
      affects: [design.resets.rst_sys, design.resets.rst_video]
      status: open
    - id: A-2
      text: "The timing stream carries every raster position, including blanking positions, as one beat per pixel clock."
      default: "Use a continuous, non-stallable AXI4-Stream raster with one frame per packet."
      reason: "The specification defines raster timing and alignment but does not prescribe an internal streaming protocol."
      affects: [timing_gen.contract.interfaces.out, pattern_gen.contract.interfaces.in, pattern_gen.contract.interfaces.out, median_filter.contract.interfaces.in, median_filter.contract.interfaces.out, vga_output.contract.interfaces.in]
      status: open
    - id: A-3
      text: "Read the frame counter and select the pattern through the test shell."
      default: "Place PATTERN at shell-window offset 0 and FRAME_COUNT at offset 4; use a Gray-code CDC for the frame counter."
      reason: "The shell window location is specified, but register offsets and the multi-bit counter CDC implementation are not."
      affects: [design.modules.pattern_gen.window_base, design.modules.timing_gen.window_base, timing_gen.contract.registers, pattern_gen.contract.registers]
      status: open

contracts:
  pixel_clock:
    schema: fpga-design-agent/contract/v1
    module: pixel_clock
    summary: Generates the video pixel clock from the board clock using an MMCM.
    clocks:
      - {name: clk, port: clk_in, max_mhz: 100}
    resets:
      - {name: rst, port: rst, clock: clk, polarity: active_low, style: async}
    ports:
      - {name: clk_in, dir: in}
      - {name: rst, dir: in}
      - {name: clk_out, dir: out, width: 1, clock: clk}
      - {name: locked, dir: out, width: 1, clock: clk, reset_value: 0}

  timing_gen:
    schema: fpga-design-agent/contract/v1
    module: timing_gen
    summary: Generates 720p60 raster coordinates, sync timing, and a completed-frame counter.
    clocks:
      - {name: clk, port: clk, max_mhz: 74.25}
    resets:
      - {name: rst, port: rst, clock: clk, polarity: active_high, style: sync}
    ports:
      - {name: clk, dir: in}
      - {name: rst, dir: in}
      - {name: m_axis_tvalid, dir: out, clock: clk, reset_value: 0}
      - {name: m_axis_tready, dir: in, clock: clk}
      - {name: m_axis_tdata, dir: out, width: 36, clock: clk}
      - {name: m_axis_tuser, dir: out, width: 0, clock: clk}
      - {name: m_axis_tlast, dir: out, clock: clk, reset_value: 0}
      - {name: frame_count, dir: out, width: 32, clock: clk, reset_value: 0}
    data_formats:
      - {name: rgb12, format: u12, packing: "three 4-bit RGB channels"}
      - {name: x11, format: u11, packing: "horizontal raster coordinate"}
      - {name: y10, format: u10, packing: "vertical raster coordinate"}
      - {name: bit1, format: u1, packing: "one raster metadata bit"}
    interfaces:
      - name: out
        protocol: axi4-stream
        role: master
        prefix: m_axis
        clock: clk
        reset: rst
        tdata:
          width: 36
          fields:
            - {name: rgb, bits: [35, 24], format: rgb12}
            - {name: x, bits: [23, 13], format: x11}
            - {name: y, bits: [12, 3], format: y10}
            - {name: active, bits: [2, 2], format: bit1}
            - {name: hsync, bits: [1, 1], format: bit1}
            - {name: vsync, bits: [0, 0], format: bit1}
        tuser: []
        tlast: "Assert on the final raster position of each frame."
        packet_beats: 1237500
        backpressure: false
        source_gaps: false
    registers:
      bus: top
      map:
        - name: FRAME_COUNT
          offset: 0x00
          access: RO
          reset: 0
          width: 32
          volatile: true
          fields:
            - {name: frame_count, bits: [31, 0], port: frame_count}
    throughput:
      - {interface: out, beats_per_cycle: 1}

  pattern_gen:
    schema: fpga-design-agent/contract/v1
    module: pattern_gen
    summary: Replaces raster RGB data with the selected colour bars or solid black.
    clocks:
      - {name: clk, port: clk, max_mhz: 74.25}
    resets:
      - {name: rst, port: rst, clock: clk, polarity: active_high, style: sync}
    ports:
      - {name: clk, dir: in}
      - {name: rst, dir: in}
      - {name: pattern_select, dir: in, width: 1, clock: clk}
      - {name: s_axis_tvalid, dir: in, clock: clk}
      - {name: s_axis_tready, dir: out, clock: clk, reset_value: 0}
      - {name: s_axis_tdata, dir: in, width: 36, clock: clk}
      - {name: s_axis_tuser, dir: in, width: 0, clock: clk}
      - {name: s_axis_tlast, dir: in, clock: clk}
      - {name: m_axis_tvalid, dir: out, clock: clk, reset_value: 0}
      - {name: m_axis_tready, dir: in, clock: clk}
      - {name: m_axis_tdata, dir: out, width: 36, clock: clk}
      - {name: m_axis_tuser, dir: out, width: 0, clock: clk}
      - {name: m_axis_tlast, dir: out, clock: clk, reset_value: 0}
    data_formats:
      - {name: rgb12, format: u12, packing: "three 4-bit RGB channels"}
      - {name: x11, format: u11, packing: "horizontal raster coordinate"}
      - {name: y10, format: u10, packing: "vertical raster coordinate"}
      - {name: bit1, format: u1, packing: "one raster metadata bit"}
    interfaces:
      - name: in
        protocol: axi4-stream
        role: slave
        prefix: s_axis
        clock: clk
        reset: rst
        tdata:
          width: 36
          fields:
            - {name: rgb, bits: [35, 24], format: rgb12}
            - {name: x, bits: [23, 13], format: x11}
            - {name: y, bits: [12, 3], format: y10}
            - {name: active, bits: [2, 2], format: bit1}
            - {name: hsync, bits: [1, 1], format: bit1}
            - {name: vsync, bits: [0, 0], format: bit1}
        tuser: []
        tlast: "Assert on the final raster position of each frame."
        packet_beats: 1237500
        backpressure: false
        source_gaps: false
      - name: out
        protocol: axi4-stream
        role: master
        prefix: m_axis
        clock: clk
        reset: rst
        tdata:
          width: 36
          fields:
            - {name: rgb, bits: [35, 24], format: rgb12}
            - {name: x, bits: [23, 13], format: x11}
            - {name: y, bits: [12, 3], format: y10}
            - {name: active, bits: [2, 2], format: bit1}
            - {name: hsync, bits: [1, 1], format: bit1}
            - {name: vsync, bits: [0, 0], format: bit1}
        tuser: []
        tlast: "Assert on the final raster position of each frame."
        packet_beats: 1237500
        backpressure: false
        source_gaps: false
    registers:
      bus: top
      map:
        - name: PATTERN
          offset: 0x00
          access: RW
          reset: 0
          width: 1
          volatile: false
          fields:
            - {name: pattern_select, bits: [0, 0], port: pattern_select}
    throughput:
      - {interface: out, beats_per_cycle: 1}

  median_filter:
    schema: fpga-design-agent/contract/v1
    module: median_filter
    summary: Applies a per-channel 3x3 median filter while carrying raster metadata with the result.
    clocks:
      - {name: clk, port: clk, max_mhz: 74.25}
    resets:
      - {name: rst, port: rst, clock: clk, polarity: active_high, style: sync}
    ports:
      - {name: clk, dir: in}
      - {name: rst, dir: in}
      - {name: s_axis_tvalid, dir: in, clock: clk}
      - {name: s_axis_tready, dir: out, clock: clk, reset_value: 0}
      - {name: s_axis_tdata, dir: in, width: 36, clock: clk}
      - {name: s_axis_tuser, dir: in, width: 0, clock: clk}
      - {name: s_axis_tlast, dir: in, clock: clk}
      - {name: m_axis_tvalid, dir: out, clock: clk, reset_value: 0}
      - {name: m_axis_tready, dir: in, clock: clk}
      - {name: m_axis_tdata, dir: out, width: 36, clock: clk}
      - {name: m_axis_tuser, dir: out, width: 0, clock: clk}
      - {name: m_axis_tlast, dir: out, clock: clk, reset_value: 0}
    data_formats:
      - {name: rgb12, format: u12, packing: "three 4-bit RGB channels"}
      - {name: x11, format: u11, packing: "horizontal raster coordinate"}
      - {name: y10, format: u10, packing: "vertical raster coordinate"}
      - {name: bit1, format: u1, packing: "one raster metadata bit"}
    interfaces:
      - name: in
        protocol: axi4-stream
        role: slave
        prefix: s_axis
        clock: clk
        reset: rst
        tdata:
          width: 36
          fields:
            - {name: rgb, bits: [35, 24], format: rgb12}
            - {name: x, bits: [23, 13], format: x11}
            - {name: y, bits: [12, 3], format: y10}
            - {name: active, bits: [2, 2], format: bit1}
            - {name: hsync, bits: [1, 1], format: bit1}
            - {name: vsync, bits: [0, 0], format: bit1}
        tuser: []
        tlast: "Assert on the final raster position of each frame."
        packet_beats: 1237500
        backpressure: false
        source_gaps: false
      - name: out
        protocol: axi4-stream
        role: master
        prefix: m_axis
        clock: clk
        reset: rst
        tdata:
          width: 36
          fields:
            - {name: rgb, bits: [35, 24], format: rgb12}
            - {name: x, bits: [23, 13], format: x11}
            - {name: y, bits: [12, 3], format: y10}
            - {name: active, bits: [2, 2], format: bit1}
            - {name: hsync, bits: [1, 1], format: bit1}
            - {name: vsync, bits: [0, 0], format: bit1}
        tuser: []
        tlast: "Assert on the final raster position of each frame."
        packet_beats: 1237500
        backpressure: false
        source_gaps: false
    throughput:
      - {interface: out, beats_per_cycle: 1}

  vga_output:
    schema: fpga-design-agent/contract/v1
    module: vga_output
    summary: Drives VGA RGB and sync outputs from the filtered raster stream, blanking RGB when required.
    clocks:
      - {name: clk, port: clk, max_mhz: 74.25}
    resets:
      - {name: rst, port: rst, clock: clk, polarity: active_high, style: sync}
    ports:
      - {name: clk, dir: in}
      - {name: rst, dir: in}
      - {name: blank_button, dir: in, width: 1, clock: async}
      - {name: pixel_locked, dir: in, width: 1, clock: async}
      - {name: red, dir: out, width: 4, clock: clk, reset_value: 0}
      - {name: green, dir: out, width: 4, clock: clk, reset_value: 0}
      - {name: blue, dir: out, width: 4, clock: clk, reset_value: 0}
      - {name: hsync, dir: out, width: 1, clock: clk, reset_value: 0}
      - {name: vsync, dir: out, width: 1, clock: clk, reset_value: 0}
      - {name: s_axis_tvalid, dir: in, clock: clk}
      - {name: s_axis_tready, dir: out, clock: clk, reset_value: 0}
      - {name: s_axis_tdata, dir: in, width: 36, clock: clk}
      - {name: s_axis_tuser, dir: in, width: 0, clock: clk}
      - {name: s_axis_tlast, dir: in, clock: clk}
    data_formats:
      - {name: rgb12, format: u12, packing: "three 4-bit RGB channels"}
      - {name: x11, format: u11, packing: "horizontal raster coordinate"}
      - {name: y10, format: u10, packing: "vertical raster coordinate"}
      - {name: bit1, format: u1, packing: "one raster metadata bit"}
    interfaces:
      - name: in
        protocol: axi4-stream
        role: slave
        prefix: s_axis
        clock: clk
        reset: rst
        tdata:
          width: 36
          fields:
            - {name: rgb, bits: [35, 24], format: rgb12}
            - {name: x, bits: [23, 13], format: x11}
            - {name: y, bits: [12, 3], format: y10}
            - {name: active, bits: [2, 2], format: bit1}
            - {name: hsync, bits: [1, 1], format: bit1}
            - {name: vsync, bits: [0, 0], format: bit1}
        tuser: []
        tlast: "Assert on the final raster position of each frame."
        packet_beats: 1237500
        backpressure: false
        source_gaps: false

module_specs:
  pixel_clock: |
    Use an MMCM to derive the 74.25 MHz pixel clock from the 100 MHz board oscillator:
    DIVCLK_DIVIDE=5, CLKFBOUT_MULT_F=37.125, and CLKOUT0_DIVIDE_F=10.
    Expose the MMCM lock indication for clock-stability blanking and the LED.
  timing_gen: |
    Generate a continuous 1650-by-750 raster at 74.25 MHz. Mark the 1280-by-720 active
    region and generate positive horizontal and vertical sync using the specified porches.
    Increment the 32-bit unsigned frame counter once per completed frame; it wraps naturally.
  pattern_gen: |
    On active coordinates, generate eight 160-pixel vertical bars in the order white,
    yellow, cyan, green, magenta, red, blue, black by default. Pattern select 0 selects
    bars; pattern select 1 selects solid black. Preserve raster metadata.
  median_filter: |
    For each active output coordinate, calculate the median independently for each
    4-bit colour channel over its 3x3 neighbourhood. At picture boundaries, clamp
    neighbourhood coordinates to the nearest active-picture coordinate. Preserve the
    corresponding coordinate, active-video indication, and sync timing through the filter.
  vga_output: |
    Drive 4-bit RGB and positive-polarity sync outputs from the filtered raster. Drive
    RGB to zero outside active video, while BTNC is pressed, while the pixel clock is
    not locked, and during reset. Consume the stream without backpressure.

requirements:
  - id: S-1
    text: "Generate VGA timing at 1280x720 and 60 Hz using a 74.25 MHz pixel clock, 1650 clocks per line (1280 active, 110 front porch, 40 sync, 220 back porch), and 750 lines per frame (720 active, 5 front porch, 5 sync, 20 back porch), with positive horizontal and vertical sync."
    proof: [simulation, hardware]
    modules: [pixel_clock, timing_gen, vga_output, top]
  - id: S-2
    text: "By default, generate eight vertical bars, each 160 pixels wide, in this order: white, yellow, cyan, green, magenta, red, blue, black."
    proof: [simulation, hardware]
    modules: [pattern_gen, top]
  - id: S-3
    text: "For pixels with a complete 3x3 neighbourhood, output the median of the nine neighbourhood values independently for each colour channel."
    proof: [simulation, formal]
    modules: [median_filter, top]
  - id: S-4
    text: "Keep the output picture, active-video indication, and horizontal and vertical sync aligned so that each output picture coordinate corresponds to the sync and active-video timing for that coordinate."
    proof: [simulation, formal]
    modules: [timing_gen, pattern_gen, median_filter, vga_output, top]
  - id: S-5
    text: "Drive all colour outputs to zero outside the active picture, while BTNC is pressed, and while the pixel clock is not stable."
    proof: [simulation, hardware]
    modules: [vga_output, top]
  - id: S-6
    text: "Illuminate LED[0] when the pixel clock is stable."
    proof: [hardware]
    modules: [pixel_clock, top]
  - id: S-7
    text: "Provide a USB-UART test shell at 115200 baud that identifies the design as VMED."
    proof: [simulation, hardware]
    modules: [top]
  - id: S-8
    text: "Through the USB-UART test shell, allow the host to select a test pattern and read a frame counter."
    proof: [simulation, hardware]
    modules: [pattern_gen, timing_gen, top]

